import { CONFIG } from './config';
import { GameRuleError } from './errors';
import { activeQuests } from './selectors';
import type { GameEvent, GameState, ISODate, LeadAction, Quest, WeekKey } from './types';
import { isSameLocalDay, weekKey } from './weeks';

// Every action is a pure function (state, payload, now) => newState.
// Ids are generated by the caller so the engine stays deterministic.

export interface CreateQuestPayload {
  id: string;
  title: string;
  boss?: string;
  deadline?: ISODate;
  isPublic?: boolean;
  notes?: string;
}
export interface UpdateQuestPayload {
  questId: string;
  patch: Partial<Pick<Quest, 'title' | 'boss' | 'deadline' | 'isPublic' | 'notes'>>;
}
export interface ActivateQuestPayload {
  questId: string;
  /** Emergency override: force a quest past the slot limit. Resets the streak. */
  override?: boolean;
}
export interface FinishQuestPayload {
  questId: string;
}
export interface KillQuestPayload {
  questId: string;
  reason: string;
  toldPeople: boolean;
}
export interface AddLeadActionPayload {
  id: string;
  questId: string;
  text: string;
  /** Defaults to the current week. */
  week?: WeekKey;
}
export interface LeadActionRefPayload {
  leadActionId: string;
}

export type GameAction =
  | ({ type: 'createQuest' } & CreateQuestPayload)
  | ({ type: 'updateQuest' } & UpdateQuestPayload)
  | ({ type: 'activateQuest' } & ActivateQuestPayload)
  | ({ type: 'finishQuest' } & FinishQuestPayload)
  | ({ type: 'killQuest' } & KillQuestPayload)
  | ({ type: 'addLeadAction' } & AddLeadActionPayload)
  | ({ type: 'completeLeadAction' } & LeadActionRefPayload)
  | ({ type: 'undoLeadAction' } & LeadActionRefPayload);

// ---------- helpers ----------

const iso = (now: Date): ISODate => now.toISOString();

function getQuest(state: GameState, questId: string): Quest {
  const quest = state.quests.find((q) => q.id === questId);
  if (!quest) throw new GameRuleError('QUEST_NOT_FOUND', 'That quest does not exist.');
  return quest;
}

function getLeadAction(state: GameState, leadActionId: string): LeadAction {
  const la = state.leadActions.find((l) => l.id === leadActionId);
  if (!la) throw new GameRuleError('LEAD_ACTION_NOT_FOUND', 'That lead action does not exist.');
  return la;
}

function requireActive(quest: Quest): void {
  if (quest.status !== 'active') {
    throw new GameRuleError('QUEST_NOT_ACTIVE', 'Only an active quest can do that.');
  }
}

function replaceQuest(state: GameState, quest: Quest): Quest[] {
  return state.quests.map((q) => (q.id === quest.id ? quest : q));
}

function replaceLeadAction(state: GameState, la: LeadAction): LeadAction[] {
  return state.leadActions.map((l) => (l.id === la.id ? la : l));
}

/** Copy `key` from `patch` onto `target` if present; drop it when set to undefined or blank. */
function applyOptional<K extends 'deadline' | 'notes'>(target: Quest, patch: UpdateQuestPayload['patch'], key: K): void {
  if (!(key in patch)) return;
  const value = patch[key]?.trim();
  if (value) target[key] = value;
  else delete target[key];
}

// ---------- actions ----------

export function createQuest(state: GameState, p: CreateQuestPayload, now: Date): GameState {
  if (state.quests.some((q) => q.id === p.id)) throw new GameRuleError('DUPLICATE_ID', 'Quest id already exists.');
  const title = p.title.trim();
  if (!title) throw new GameRuleError('TITLE_REQUIRED', 'Give the quest a title.');
  const quest: Quest = {
    id: p.id,
    title,
    boss: (p.boss ?? '').trim(),
    isPublic: p.isPublic ?? false,
    status: 'vault',
    createdAt: iso(now),
  };
  if (p.deadline) quest.deadline = p.deadline;
  if (p.notes?.trim()) quest.notes = p.notes.trim();
  return { ...state, quests: [...state.quests, quest] };
}

export function updateQuest(state: GameState, p: UpdateQuestPayload, _now: Date): GameState {
  const quest = getQuest(state, p.questId);
  if (quest.status === 'finished' || quest.status === 'killed') {
    throw new GameRuleError('QUEST_CLOSED', 'A finished or killed quest can no longer be edited.');
  }
  const next: Quest = { ...quest };
  if (p.patch.title !== undefined) next.title = p.patch.title.trim();
  if (p.patch.boss !== undefined) next.boss = p.patch.boss.trim();
  if (p.patch.isPublic !== undefined) next.isPublic = p.patch.isPublic;
  applyOptional(next, p.patch, 'deadline');
  applyOptional(next, p.patch, 'notes');
  if (!next.title) throw new GameRuleError('TITLE_REQUIRED', 'Give the quest a title.');
  if (next.status === 'active' && !next.boss) {
    throw new GameRuleError('BOSS_REQUIRED', 'An active quest needs a boss: one sentence that defines done.');
  }
  return { ...state, quests: replaceQuest(state, next) };
}

export function activateQuest(state: GameState, p: ActivateQuestPayload, now: Date): GameState {
  const quest = getQuest(state, p.questId);
  if (quest.status !== 'vault') throw new GameRuleError('QUEST_NOT_IN_VAULT', 'Only a quest in the Vault can be activated.');
  if (!quest.boss.trim()) {
    throw new GameRuleError('BOSS_REQUIRED', 'Define the boss first: one sentence that says when this quest is done.');
  }
  const slotsFull = activeQuests(state).length >= CONFIG.maxActiveQuests;
  if (slotsFull && !p.override) {
    throw new GameRuleError('SLOTS_FULL', 'Both quest slots are full. Finish or kill a quest first.');
  }
  const events: GameEvent[] = slotsFull
    ? [
        { type: 'OVERRIDE_USED', at: iso(now), questId: quest.id },
        { type: 'STREAK_RESET', at: iso(now), reason: 'override' },
      ]
    : [];
  return {
    ...state,
    quests: replaceQuest(state, { ...quest, status: 'active', activatedAt: iso(now) }),
    events: [...state.events, ...events],
  };
}

export function finishQuest(state: GameState, p: FinishQuestPayload, now: Date): GameState {
  const quest = getQuest(state, p.questId);
  requireActive(quest);
  return {
    ...state,
    quests: replaceQuest(state, { ...quest, status: 'finished', closedAt: iso(now) }),
    events: [...state.events, { type: 'BOSS_DEFEATED', at: iso(now), questId: quest.id }],
  };
}

export function killQuest(state: GameState, p: KillQuestPayload, now: Date): GameState {
  const quest = getQuest(state, p.questId);
  requireActive(quest);
  const reason = p.reason.trim();
  if (!reason) throw new GameRuleError('KILL_REASON_REQUIRED', 'Write down why you are stopping this quest.');
  if (p.toldPeople !== true) {
    throw new GameRuleError('KILL_MUST_TELL_PEOPLE', 'Tell the people involved before you kill the quest.');
  }
  return {
    ...state,
    quests: replaceQuest(state, { ...quest, status: 'killed', closedAt: iso(now), killReason: reason }),
    events: [...state.events, { type: 'QUEST_KILLED', at: iso(now), questId: quest.id }],
  };
}

export function addLeadAction(state: GameState, p: AddLeadActionPayload, now: Date): GameState {
  if (state.leadActions.some((l) => l.id === p.id)) throw new GameRuleError('DUPLICATE_ID', 'Lead action id already exists.');
  requireActive(getQuest(state, p.questId));
  const text = p.text.trim();
  if (!text) throw new GameRuleError('LEAD_ACTION_TEXT_REQUIRED', 'Describe the lead action.');
  const week = p.week ?? weekKey(now);
  const count = state.leadActions.filter((l) => l.questId === p.questId && l.week === week).length;
  if (count >= CONFIG.maxLeadActionsPerQuestPerWeek) {
    throw new GameRuleError(
      'LEAD_ACTION_LIMIT',
      `At most ${CONFIG.maxLeadActionsPerQuestPerWeek} lead actions per quest per week.`,
    );
  }
  return { ...state, leadActions: [...state.leadActions, { id: p.id, questId: p.questId, week, text }] };
}

export function completeLeadAction(state: GameState, p: LeadActionRefPayload, now: Date): GameState {
  const la = getLeadAction(state, p.leadActionId);
  if (la.doneAt) throw new GameRuleError('LEAD_ACTION_ALREADY_DONE', 'This lead action is already done.');
  requireActive(getQuest(state, la.questId));
  return {
    ...state,
    leadActions: replaceLeadAction(state, { ...la, doneAt: iso(now) }),
    events: [...state.events, { type: 'LEAD_ACTION_DONE', at: iso(now), leadActionId: la.id, questId: la.questId }],
  };
}

export function undoLeadAction(state: GameState, p: LeadActionRefPayload, now: Date): GameState {
  const la = getLeadAction(state, p.leadActionId);
  if (!la.doneAt) throw new GameRuleError('LEAD_ACTION_NOT_DONE', 'This lead action is not done yet.');
  if (!isSameLocalDay(new Date(la.doneAt), now)) {
    throw new GameRuleError('UNDO_WINDOW_CLOSED', 'A lead action can only be unticked on the day it was done.');
  }
  const { doneAt: _removed, ...rest } = la;
  return {
    ...state,
    leadActions: replaceLeadAction(state, rest),
    events: state.events.filter((e) => !(e.type === 'LEAD_ACTION_DONE' && e.leadActionId === la.id)),
  };
}

export function applyAction(state: GameState, action: GameAction, now: Date): GameState {
  switch (action.type) {
    case 'createQuest':
      return createQuest(state, action, now);
    case 'updateQuest':
      return updateQuest(state, action, now);
    case 'activateQuest':
      return activateQuest(state, action, now);
    case 'finishQuest':
      return finishQuest(state, action, now);
    case 'killQuest':
      return killQuest(state, action, now);
    case 'addLeadAction':
      return addLeadAction(state, action, now);
    case 'completeLeadAction':
      return completeLeadAction(state, action, now);
    case 'undoLeadAction':
      return undoLeadAction(state, action, now);
  }
}
